		// f(j, i, m) = sum_{k=0}^{i} (-1)^k * C(i, k) * C(j - k*(m+1) + i - 1, i - 1)
		// if j - k*(m+1) >= 0, else 0

		f := func(j, i, m int) int {
			if j < 0 {
				return 0
			}
			if i == 0 {
				if j == 0 {
					return 1
				}
				return 0
			}
			res := 0
			for k := 0; k <= i; k++ {
				val := j - k*(m+1)
				if val < 0 {
					break
				}
				term := C[i][k] * C[val+i-1][i-1] % MOD
				if k%2 == 0 {
					res = (res + term) % MOD
				} else {
					res = (res - term + MOD) % MOD
				}
			}
			return res
		}

		// For m < a1:
		// Number of ways where max <= a1-1
		waysLess := f(remaining, p-1, a1-1)

		// For m == a1:
		// Sum over k of C(p-1, k) * f(remaining - k*a1, p-1-k, a1-1) * 1/(k+1)
		waysEqual := 0
		for k := 1; k <= p-1; k++ {
			if remaining-k*a1 < 0 {
				break
			}
			term := C[p-1][k] * f(remaining-k*a1, p-1-k, a1-1) % MOD
			term = term * modInv(k+1) % MOD
			waysEqual = (waysEqual + term) % MOD
		}

		contribution := (waysLess + waysEqual) % MOD
		win = (win + contribution) % MOD
	}

	// Probability = win / total
	if total == 0 {
		fmt.Println(0)
		return
	}
	result := win * modInv(total) % MOD
	fmt.Println(result)
}
