	distribute := func(j, n, cap int) int {
		if j < 0 {
			return 0
		}
		if n == 0 {
			if j == 0 {
				return 1
			}
			return 0
		}
		result := 0
		for i := 0; i <= n; i++ {
			// Choose i players to give cap+1 or more
			// Remaining: j - i*(cap+1) distributed among n players each >= 0
			// = C(j - i*(cap+1) + n - 1, n - 1)
			rem := j - i*(cap+1)
			if rem < 0 {
				break
			}
			term := C(n, i) * C(rem+n-1, n-1) % MOD
			if i%2 == 1 {
				result = (result - term + MOD) % MOD
			} else {
				result = (result + term) % MOD
			}
