		remaining := s - x
		// distribute remaining among p-1 players each in [0, x]
		// ways where all < x: distribute(remaining, p-1, x-1)
		waysStrict := distribute(remaining, p-1, x-1)
		// contribution from unique max: waysStrict * 1
		numerator = (numerator + waysStrict) % MOD

		// For tied states: m players (out of p-1) have score x, rest have score < x
		for m := 1; m <= p-1; m++ {
			// Choose m players to have score x: C(p-1, m)
			// Remaining goals: remaining - m*x
			// Distribute among p-1-m players each in [0, x-1]
			rem := remaining - m*x
			if rem < 0 {
				break
			}
			ways := C(p-1, m) * distribute(rem, p-1-m, x-1) % MOD
			// Each such state contributes 1/(m+1)
			invMPlus1 := modInv(m + 1)
			numerator = (numerator + ways*invMPlus1) % MOD
		}
	}

	// Answer = numerator / totalStates
	if totalStates == 0 {
		fmt.Println(0)
		return
	}
	ans := numerator * modInv(totalStates) % MOD
	fmt.Println(ans)
}

func modInv(a int) int {
	return powMod(a, MOD-2)
}

func powMod(a, b int) int {
	result := 1
	base := a % MOD
	for b > 0 {
		if b%2 == 1 {
			result = result * base % MOD
		}
		base = base * base % MOD
		b /= 2
	}
	return result
}
