		// We can compute for each a1 the total contribution to favorable cases.

		// Alternative approach: use the formula
		// favorable += ways_all_le_a1_minus_1 (Hasan strictly wins)
		//           + sum_{t=1}^{p-1} C(p-1, t) * f(rem - t*a1, p-1-t, a1-1) * inv[t+1]
		// where f(sum, count, max) is the number of ways to distribute sum among count players each <= max

		// But we already have ways_all_le_a1 and ways_all_le_a1_minus_1
		// Let's compute the tie cases separately

		// For tie cases: at least one other player has score a1
		// We need to count, for each t from 1 to p-1:
		// number of ways to choose t players to have score a1, and the remaining p-1-t players have score < a1 and sum to rem - t*a1
		// Then multiply by 1/(t+1)

		// f(n, k, m) = number of ways to distribute n among k players each in [0, m]
		// We can compute this with DP

		// Let's precompute f for all needed values
		// f(n, k, m) where n <= s, k <= p, m <= s

		// Actually, let's just compute it on the fly for each a1

		// For the tie part:
		tie_contrib := 0
		for t := 1; t <= p-1; t++ {
			if t*a1 > rem {
				break
			}
			// Choose t players from p-1
			comb := 1
			for i := 0; i < t; i++ {
				comb = comb * (p - 1 - i) % MOD * inv[i+1] % MOD
			}
			// Remaining sum for p-1-t players, each < a1 (i.e., <= a1-1)
			rem_sum := rem - t*a1
			if rem_sum < 0 {
				continue
			}
			// f(rem_sum, p-1-t, a1-1)
			ways := f(rem_sum, p-1-t, a1-1)
			tie_contrib = (tie_contrib + comb*ways%MOD*inv[t+1]) % MOD
		}

		favorable = (favorable + ways_all_le_a1_minus_1 + tie_contrib) % MOD
	}

	// Probability = favorable / total
	if total == 0 {
		fmt.Println(0)
		return
	}
	result := favorable * modpow(total, MOD-2) % MOD
	fmt.Println(result)
}

// f(n, k, m) = number of ways to distribute n among k players each in [0, m]
func f(n, k, m int) int {
	if n < 0 || k < 0 {
		return 0
	}
	if k == 0 {
		if n == 0 {
			return 1
		}
		return 0
	}
	if m < 0 {
		return 0
	}
	// dp[i][j] = ways to distribute j among first i players
	dp := make([][]int, k+1)
	for i := range dp {
		dp[i] = make([]int, n+1)
	}
	dp[0][0] = 1
	for i := 1; i <= k; i++ {
		for j := 0; j <= n; j++ {
			for x := 0; x <= m && x <= j; x++ {
				dp[i][j] = (dp[i][j] + dp[i-1][j-x]) % MOD
			}
		}
	}
	return dp[k][n]
}
