		w1 := ways(p-1, rem, a1-1)
		win = (win + w1) % MOD

		// Case 2: some other players have score == a1
		// For each k from 1 to p-1, choose k players to have score a1,
		// and the remaining p-1-k players have score < a1.
		// The remaining sum is rem - k*a1, distributed into p-1-k players each <= a1-1.
		for k := 1; k <= p-1; k++ {
			if k*a1 > rem {
				break
			}
			rem2 := rem - k*a1
			if rem2 < 0 {
				break
			}
			// Choose k players from p-1
			choose := C(p-1, k)
			// Distribute rem2 into p-1-k players each <= a1-1
			w2 := ways(p-1-k, rem2, a1-1)
			// Probability of winning in this case: 1/(k+1)
			prob := (MOD + 1 - modInv(k+1)) % MOD // This is wrong, should be modInv(k+1)
			prob = modInv(k + 1)
			win = (win + choose*w2%MOD*prob) % MOD
		}
	}

	// Probability = win / total
	if total == 0 {
		fmt.Println(0)
		return
	}
	ans := win * modInv(total) % MOD
	fmt.Println(ans)
}
