package main

import (
	"bufio"
	"fmt"
	"os"
)

const MOD = 998244353

var inv [5010]int

func modInv(a int) int {
	return pow(a, MOD-2)
}

func pow(a, b int) int {
	res := 1
	for b > 0 {
		if b&1 == 1 {
			res = res * a % MOD
		}
		a = a * a % MOD
		b >>= 1
	}
	return res
}

func main() {
	in := bufio.NewReader(os.Stdin)
	var p, s, r int
	fmt.Fscan(in, &p, &s, &r)

	// Precompute inverses
	for i := 1; i <= 5000; i++ {
		inv[i] = modInv(i)
	}

	// dp[i][j] = number of ways to distribute j points among i players (each >=0)
	dp := make([][]int, p+1)
	for i := range dp {
		dp[i] = make([]int, s+1)
	}
	dp[0][0] = 1
	for i := 1; i <= p; i++ {
		for j := 0; j <= s; j++ {
			for k := 0; k <= j; k++ {
				dp[i][j] = (dp[i][j] + dp[i-1][j-k]) % MOD
			}
		}
	}

	// Total valid states: a1 >= r, sum = s
	total := 0
	for a1 := r; a1 <= s; a1++ {
		rem := s - a1
		total = (total + dp[p-1][rem]) % MOD
	}

	// Winning states: a1 > max(a2..ap)
	win := 0
	for a1 := r; a1 <= s; a1++ {
		rem := s - a1
		// Count ways where all other p-1 players have score <= a1-1
		// and sum = rem
		// Use inclusion-exclusion or direct DP
		// dp2[i][j] = ways to distribute j among i players each <= a1-1
		dp2 := make([][]int, p)
		for i := range dp2 {
			dp2[i] = make([]int, rem+1)
		}
		dp2[0][0] = 1
		for i := 1; i < p; i++ {
			for j := 0; j <= rem; j++ {
				for k := 0; k <= j && k <= a1-1; k++ {
					dp2[i][j] = (dp2[i][j] + dp2[i-1][j-k]) % MOD
				}
			}
		}
		win = (win + dp2[p-1][rem]) % MOD
	}

	// Probability = win / total
	if total == 0 {
		fmt.Println(0)
		return
	}
	result := win * modInv(total) % MOD
	fmt.Println(result)
}
