package main

import (
	"bufio"
	"fmt"
	"os"
)

const MOD = 998244353

var inv [5005]int

func modInv(a int) int {
	return powMod(a, MOD-2)
}

func powMod(a, b int) int {
	res := 1
	for b > 0 {
		if b&1 == 1 {
			res = res * a % MOD
		}
		a = a * a % MOD
		b >>= 1
	}
	return res
}

func main() {
	in := bufio.NewReader(os.Stdin)
	var p, s, r int
	fmt.Fscan(in, &p, &s, &r)

	// Precompute inverses
	for i := 1; i <= s; i++ {
		inv[i] = modInv(i)
	}

	// dp[i][j] = number of ways to distribute j goals among i players (each >=0)
	// dp[i][j] = C(j+i-1, i-1)
	// We'll compute using dp
	// dp[i][j] = dp[i][j-1] + dp[i-1][j]
	// But to avoid overflow, use combinatorics with modular inverses

	// Precompute combinations C(n,k) mod MOD for n up to s+p
	// Actually, we need C(j+i-1, i-1) for i up to p, j up to s
	// Let's precompute factorials and inverse factorials up to s+p
	maxN := s + p
	fact := make([]int, maxN+1)
	ifact := make([]int, maxN+1)
	fact[0] = 1
	for i := 1; i <= maxN; i++ {
		fact[i] = fact[i-1] * i % MOD
	}
	ifact[maxN] = modInv(fact[maxN])
	for i := maxN - 1; i >= 0; i-- {
		ifact[i] = ifact[i+1] * (i+1) % MOD
	}

	comb := func(n, k int) int {
		if k < 0 || k > n {
			return 0
		}
		return fact[n] * ifact[k] % MOD * ifact[n-k] % MOD
	}

	// dp[i][j] = number of ways to distribute j goals among i players (each >=0)
	// = C(j+i-1, i-1)
	ways := func(i, j int) int {
		if i == 0 {
			if j == 0 {
				return 1
			}
			return 0
		}
		return comb(j+i-1, i-1)
	}

	// Total valid states: a1 >= r, sum = s
	// a1 can be from r to s
	// For each a1, remaining p-1 players sum to s-a1
	total := 0
	for a1 := r; a1 <= s; a1++ {
		rem := s - a1
		total = (total + ways(p-1, rem)) % MOD
	}

	// Favorable: a1 is strictly greater than all others, or tied and chosen
	// Case 1: a1 > all others (a1 > max(a2..ap))
	// Case 2: a1 = max, and there are k players with score = a1 (including a1), probability 1/k
	// So favorable = sum over a1 from r to s of [ways where a1 is strictly max + sum over k>=1 (1/k * ways where exactly k players including a1 have score a1 and rest < a1)]

	// Let's compute for each a1:
	// f(a1) = number of ways where a1 is strictly greater than all others
	// g(a1) = sum over k=1 to p (1/k * number of ways where exactly k players (including a1) have score a1, and rest have score < a1)
	// favorable = sum over a1 of (f(a1) + g(a1))

	// f(a1): a2..ap all < a1, sum = s-a1
	// This is the number of ways to distribute s-a1 into p-1 parts each in [0, a1-1]
	// = coefficient of x^(s-a1) in (1+x+...+x^(a1-1))^(p-1)
	// = sum_{j=0}^{p-1} (-1)^j * C(p-1, j) * C(s-a1 - j*a1 + p-2, p-2)  [inclusion-exclusion]
	// But easier: use dp or the formula with inclusion-exclusion

	// Number of ways to distribute n into k parts each <= m:
	// = sum_{j=0}^{k} (-1)^j * C(k, j) * C(n - j*(m+1) + k - 1, k - 1)
	// Here m = a1-1, so m+1 = a1
	// n = s-a1, k = p-1
	// = sum_{j=0}^{p-1} (-1)^j * C(p-1, j) * C(s-a1 - j*a1 + p-2, p-2)

	favorable := 0
	for a1 := r; a1 <= s; a1++ {
		rem := s - a1
		if rem < 0 {
			continue
		}
		// f(a1): all others < a1
		// distribute rem into p-1 parts each in [0, a1-1]
		// = sum_{j=0}^{p-1} (-1)^j * C(p-1, j) * C(rem - j*a1 + p-2, p-2)
		f := 0
		for j := 0; j <= p-1; j++ {
			nj := rem - j*a1
			if nj < 0 {
				break
			}
			c := comb(nj+p-2, p-2)
			if j%2 == 0 {
				f = (f + comb(p-1, j)*c) % MOD
			} else {
				f = (f - comb(p-1, j)*c) % MOD
			}
		}

		// g(a1): exactly k players (including a1) have score a1, rest < a1
		// Choose k-1 other players from p-1 to also have score a1: C(p-1, k-1)
		// Remaining p-k players have score < a1, sum = rem - (k-1)*a1
		// Number of ways: C(p-1, k-1) * [distribute rem-(k-1)*a1 into p-k parts each in [0, a1-1]]
		// Contribution: (1/k) * C(p-1, k-1) * ways_to_distribute
		g := 0
		for k := 1; k <= p; k++ {
			// k-1 other players have score a1
			used := (k - 1) * a1
			left := rem - used
			if left < 0 {
				break
			}
			// distribute left into p-k parts each in [0, a1-1]
			// = sum_{j=0}^{p-k} (-1)^j * C(p-k, j) * C(left - j*a1 + p-k-1, p-k-1)
			waysLeft := 0
			if p-k == 0 {
				if left == 0 {
					waysLeft = 1
				}
			} else {
				for j := 0; j <= p-k; j++ {
					nj := left - j*a1
					if nj < 0 {
						break
					}
					c := comb(nj+p-k-1, p-k-1)
					if j%2 == 0 {
						waysLeft = (waysLeft + comb(p-k, j)*c) % MOD
					} else {
						waysLeft = (waysLeft - comb(p-k, j)*c) % MOD
					}
				}
			}
			contrib := comb(p-1, k-1) * waysLeft % MOD
			contrib = contrib * modInv(k) % MOD
			g = (g + contrib) % MOD
		}

		favorable = (favorable + f + g) % MOD
	}

	// Probability = favorable / total
	// = favorable * inv(total) mod MOD
	result := favorable * modInv(total) % MOD
	if result < 0 {
		result += MOD
	}
	fmt.Println(result)
}
